conv_transpose3d_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void conv_transpose3d_kernel(
    const float* input,
    const float* weight,
    const float* bias,
    float* output,
    int batch_size,
    int in_channels,
    int out_channels,
    int input_depth,
    int input_height,
    int input_width,
    int kernel_size,
    int stride,
    int padding,
    int groups,
    int output_depth,
    int output_height,
    int output_width,
    int in_channels_per_group,
    int out_channels_per_group
) {
    int n = blockIdx.x;
    int oc = blockIdx.y;
    int od = blockIdx.z / output_height;
    int oh = blockIdx.z % output_height;
    int ow = threadIdx.x;

    if (n >= batch_size || oc >= out_channels || od >= output_depth || oh >= output_height || ow >= output_width) return;

    int g = oc / out_channels_per_group;
    int oc_in_group = oc % out_channels_per_group;

    float val = 0.0f;

    for (int kd = 0; kd < kernel_size; ++kd) {
        for (int kh = 0; kh < kernel_size; ++kh) {
            for (int kw = 0; kw < kernel_size; ++kw) {
                int id = (od - kd + padding) / stride;
                int ih = (oh - kh + padding) / stride;
                int iw = (ow - kw + padding) / stride;

                if ((od - kd + padding) % stride != 0) continue;
                if ((oh - kh + padding) % stride != 0) continue;
                if ((ow - kw + padding) % stride != 0) continue;
                if (id < 0 || id >= input_depth) continue;
                if (ih < 0 || ih >= input_height) continue;
                if (iw < 0 || iw >= input_width) continue;

                for (int icg = 0; icg < in_channels_per_group; ++icg) {
                    int ic = g * in_channels_per_group + icg;

                    float w = weight[ic * (out_channels_per_group * kernel_size * kernel_size * kernel_size) 
                                    + oc_in_group * (kernel_size * kernel_size * kernel_size)
                                    + kd * (kernel_size * kernel_size) 
                                    + kh * kernel_size 
                                    + kw];

                    float v = input[n * (in_channels * input_depth * input_height * input_width)
                                  + ic * (input_depth * input_height * input_width)
                                  + id * (input_height * input_width)
                                  + ih * input_width
                                  + iw];

                    val += w * v;
                }
            }
        }
    }

    if (bias) val += bias[oc];

    output[n * (out_channels * output_depth * output_height * output_width)
          + oc * (output_depth * output_height * output_width)
          + od * (output_height * output_width)
          + oh * output_width
          + ow] = val;
}

torch::Tensor conv_transpose3d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int kernel_size,
    int stride,
    int padding,
    int groups,
    int output_padding
) {
    int batch_size = input.size(0);
    int in_channels = input.size(1);
    int input_depth = input.size(2);
    int input_height = input.size(3);
    int input_width = input.size(4);

    int out_channels = weight.size(1) * groups;
    int output_depth = (input_depth - 1) * stride - 2 * padding + kernel_size + output_padding;
    int output_height = (input_height - 1) * stride - 2 * padding + kernel_size + output_padding;
    int output_width = (input_width - 1) * stride - 2 * padding + kernel_size + output_padding;

    auto output = torch::zeros({batch_size, out_channels, output_depth, output_height, output_width}, input.options());

    int in_channels_per_group = in_channels / groups;
    int out_channels_per_group = out_channels / groups;

    dim3 grid_dim(batch_size, out_channels, output_depth * output_height);
    int block_dim = output_width;

    conv_transpose3d_kernel<<<grid_dim, block_dim>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.defined() ? bias.data_ptr<float>() : nullptr,
        output.data_ptr<float>(),
        batch_size,
        in_channels,
        out_channels,
        input_depth,
        input_height,
        input_width,
        kernel_size,
        stride,
        padding,
        groups,
        output_depth,
        output_height,
        output_width,
        in_channels_per_group,
        out_channels_per_group
    );

    return output;
}
"""

conv_transpose3d_cpp_source = """
torch::Tensor conv_transpose3d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int kernel_size,
    int stride,
    int padding,
    int groups,
    int output_padding
);
"""

conv_transpose3d = load_inline(
    name='conv_transpose3d',
    cpp_sources=conv_transpose3d_cpp_source,
    cuda_sources=conv_transpose3d_source,
    functions=['conv_transpose3d_cuda'],
    verbose=False
)

class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, output_padding: int = 0, groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.output_padding = output_padding
        self.groups = groups

        self.weight = nn.Parameter(torch.Tensor(
            in_channels,
            out_channels // groups,
            kernel_size,
            kernel_size,
            kernel_size
        ))

        if bias:
            self.bias = nn.Parameter(torch.Tensor(out_channels))
        else:
            self.register_parameter('bias', None)

        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in, _ = nn.init._calculate_fan_in_and_fan_out(self.weight)
            bound = 1 / math.sqrt(fan_in)
            nn.init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return conv_transpose3d.conv_transpose3d_cuda(
            x, 
            self.weight,
            self.bias if self.bias is not None else torch.tensor([]).to(x.device),
            self.kernel_size,
            self.stride,
            self.padding,
            self.groups,
            self.output_padding
        )
